#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode creates ScoreTracker with NewObject but stores it in a raw pointer that is not a UPROPERTY. In the packaged shipping build the Unreal garbage collector collected the object while the match was running (log: 'LogGarbage: Collecting garbage: 412 objects purged' at 21:05:13, before the crash at 21:05:27), leaving ScoreTracker dangling. When the first goal was scored ('LogArena: Display: Goal for team 1' at 21:05:27:903), AArenaGameMode::OnGoalScored called ScoreTracker->AddPoints() on the freed object, producing EXCEPTION_ACCESS_VIOLATION (stack: UArenaScoreTracker::AddPoints() [ArenaScoreTracker.cpp:18] called from AArenaGameMode::OnGoalScored [ArenaGameMode.cpp:38]). Editor runs did not hit it because GC only needs to run after the tracker is created and before a goal is scored, which did not happen in the editor sessions. Fix applied: ScoreTracker is now a UPROPERTY (TObjectPtr<UArenaScoreTracker>) in ArenaGameMode.h so the GC keeps it alive.",
  "no_colors_cause": "The HUD palette asset /Game/Data/Palettes/DA_Primary was not included in the packaged build, so at runtime LoadObject fails and the HUD falls back to gray. Packaging is set with bCookAll=False, so only the cooked map /Game/Maps/Arena, its referenced assets, and DirectoriesToAlwaysCook (previously only /Game/Data/Effects) are packaged. DA_Primary is not referenced by any UPROPERTY or level actor - ArenaGameMode loads it with LoadObject from a hardcoded path string - so the cooker has no reference to follow and the asset was excluded from the pak. Log evidence: 'LogStreaming: Error: Couldn't find file for package /Game/Data/Palettes/DA_Primary requested by async loading code', 'LogUObjectGlobals: Warning: Failed to find object 'ArenaPalette /Game/Data/Palettes/DA_Primary.DA_Primary'', 'LogArena: Warning: Palette is null, using fallback gray' at startup. It works in the editor because the asset exists on disk. Fix applied: added +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to Config/DefaultGame.ini so the palette is always cooked."
}
